// ============================================================================
// TRADING SIGNAL MODEL
// ============================================================================
//
// Module: models/trading_signal.rs
// Purpose: Data structures for trading signals generated by the analyzer service
//
// OVERVIEW:
// This module defines the TradingSignal struct that represents trading opportunities
// identified by the analyzer service. Signals are sent from analyzer to executor
// for execution.
//
// SIGNAL STRUCTURE:
//
// TradingSignal:
// - signal_id: UUID                    // Unique identifier
// - strategy: String                   // "arbitrage", "momentum", "sentiment"
// - confidence: f64 (0.0-1.0)          // Strength of signal (Kelly criterion input)
// - market_id: String                  // Target market
// - side: TradeSide                    // Buy YES or Buy NO
// - suggested_size: f64                // Contracts recommended (optional, executor may override)
// - max_slippage: f64                  // Acceptable price deviation (e.g., 0.01 = 1%)
// - timestamp: i64                     // When signal generated
// - metadata: JsonValue                // Arbitrage details, correlation data, etc.
// - ttl_ms: u64                        // Time-to-live (signal expires if not executed)
//
// SIGNAL TYPES:
//
// 1. Arbitrage Signal:
//    - strategy: "arbitrage"
//    - Generated when price discrepancy exists between markets
//    - metadata contains: buy_market, sell_market, profit_percent
//
// 2. Momentum Signal:
//    - strategy: "momentum"
//    - Generated when price moves significantly
//    - metadata contains: price_change_percent, ema_value
//
// 3. Sentiment Signal:
//    - strategy: "sentiment"
//    - Generated from news/social media analysis
//    - metadata contains: sentiment_score, source_urls
//
// SIGNAL LIFECYCLE:
//
// 1. Generated by analyzer service
//    - Analyzer emits signal when conditions are met
//    - Signal has confidence score (0.0-1.0)
//
// 2. Sent to executor via channel
//    - Executor receives signal and validates it
//    - Checks: market is open, position limits, cooldown
//
// 3. Executed or expired
//    - If executed: signal leads to trade
//    - If ttl_ms passes: signal expires
//    - If rejected: signal is dropped with reason
//
// CONFIDENCE SCORE:
//
// The confidence score (0.0-1.0) indicates signal strength:
// - 0.9-1.0: Very high confidence (clear arbitrage)
// - 0.7-0.9: High confidence (strong momentum)
// - 0.5-0.7: Medium confidence (moderate edge)
// - 0.3-0.5: Low confidence (weaker signal)
// - 0.0-0.3: Very low confidence (avoid)
//
// Used with Kelly criterion for position sizing:
// position_size = confidence * Kelly_fraction * bankroll
//
// USAGE:
//
// Creating a signal:
// ```rust
// let signal = TradingSignal {
//     signal_id: uuid::Uuid::new_v4().to_string(),
//     strategy: "arbitrage".to_string(),
//     confidence: 0.85,
//     market_id: "polymarket-btc-100k".to_string(),
//     side: TradeSide::Buy,
//     suggested_size: 100.0,
//     max_slippage: 0.01,
//     timestamp: Utc::now().timestamp(),
//     metadata: serde_json::json!({
//         "buy_market": "polymarket",
//         "sell_market": "kalshi",
//         "profit_percent": 0.02
//     }),
//     ttl_ms: 5000,
// };
// ```
//
// FUTURE ENHANCEMENTS:
// - Add signal cancellation mechanism
// - Add signal chaining (combine related signals)
// - Add signal feedback loop (track execution results)
// ============================================================================

use serde::{Deserialize, Serialize};
use serde_json::Value as JsonValue;
use crate::models::market::TradeSide;

/// Trading signal generated by the analyzer service
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct TradingSignal {
    /// Unique identifier for this signal
    pub signal_id: String,
    
    /// Strategy that generated this signal: "arbitrage", "momentum", "sentiment"
    pub strategy: String,
    
    /// Confidence level (0.0-1.0) indicating signal strength
    pub confidence: f64,
    
    /// Target market ID for execution
    pub market_id: String,
    
    /// Trade direction (Buy YES or Buy NO)
    pub side: TradeSide,
    
    /// Suggested position size in contracts (executor may override)
    pub suggested_size: f64,
    
    /// Maximum acceptable slippage (e.g., 0.01 = 1%)
    pub max_slippage: f64,
    
    /// Unix timestamp when signal was generated
    pub timestamp: i64,
    
    /// Additional metadata (strategy-specific details)
    pub metadata: JsonValue,
    
    /// Time-to-live in milliseconds (signal expires after this duration)
    pub ttl_ms: u64,
}

impl TradingSignal {
    /// Create a new trading signal
    pub fn new(
        signal_id: String,
        strategy: String,
        confidence: f64,
        market_id: String,
        side: TradeSide,
        suggested_size: f64,
        max_slippage: f64,
        timestamp: i64,
        metadata: JsonValue,
        ttl_ms: u64,
    ) -> Self {
        Self {
            signal_id,
            strategy,
            confidence,
            market_id,
            side,
            suggested_size,
            max_slippage,
            timestamp,
            metadata,
            ttl_ms,
        }
    }
    
    /// Check if signal has expired
    pub fn is_expired(&self, current_time: i64) -> bool {
        current_time - self.timestamp > self.ttl_ms as i64
    }
    
    /// Validate signal fields
    pub fn is_valid(&self) -> bool {
        self.confidence >= 0.0 && self.confidence <= 1.0 &&
        self.max_slippage >= 0.0 && self.max_slippage <= 1.0 &&
        self.suggested_size > 0.0 &&
        !self.signal_id.is_empty() &&
        !self.strategy.is_empty() &&
        !self.market_id.is_empty()
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::models::market::TradeSide;
    
    #[test]
    fn test_create_trading_signal() {
        let signal = TradingSignal::new(
            "sig-123".to_string(),
            "arbitrage".to_string(),
            0.85,
            "polymarket-btc".to_string(),
            TradeSide::Buy,
            100.0,
            0.01,
            1704067200,
            serde_json::json!({"profit": 0.02}),
            5000,
        );
        
        assert_eq!(signal.signal_id, "sig-123");
        assert_eq!(signal.strategy, "arbitrage");
        assert_eq!(signal.confidence, 0.85);
        assert_eq!(signal.side, TradeSide::Buy);
    }
    
    #[test]
    fn test_signal_validity() {
        let valid_signal = TradingSignal::new(
            "sig-123".to_string(),
            "momentum".to_string(),
            0.75,
            "market-456".to_string(),
            TradeSide::Sell,
            50.0,
            0.02,
            1704067200,
            serde_json::json!({}),
            3000,
        );
        
        assert!(valid_signal.is_valid());
        
        let invalid_signal = TradingSignal::new(
            "".to_string(),  // Empty ID
            "momentum".to_string(),
            0.75,
            "market-456".to_string(),
            TradeSide::Sell,
            50.0,
            0.02,
            1704067200,
            serde_json::json!({}),
            3000,
        );
        
        assert!(!invalid_signal.is_valid());
    }
    
    #[test]
    fn test_signal_expiration() {
        let signal = TradingSignal::new(
            "sig-123".to_string(),
            "momentum".to_string(),
            0.75,
            "market-456".to_string(),
            TradeSide::Buy,
            50.0,
            0.02,
            1704067200,  // timestamp
            serde_json::json!({}),
            5000,  // 5 second TTL
        );
        
        // Within TTL
        assert!(!signal.is_expired(1704067202));
        
        // At TTL boundary
        assert!(!signal.is_expired(1704067205));
        
        // After TTL
        assert!(signal.is_expired(1704067210));
    }
}
